const $=id=>document.getElementById(id);
const sample=`00:00 Most people wait for permission to start. I did too.
00:08 I thought I needed a better camera, a better idea, and a bigger audience.
00:16 But here's the thing nobody tells you: confidence is a result, not a requirement.
00:25 You don't become ready and then begin. You begin, and that's how you become ready.
00:35 Make one small thing today. Something imperfect that actually exists.
00:45 My first ten videos were terrible. The eleventh wasn't great either.
00:53 But each one taught me something that planning never could.
01:02 The secret? Stop measuring your first chapter against someone else's highlight reel.
01:12 Give yourself permission to be a beginner. That's where the interesting work starts.
01:22 Here's a simple trick that changed how I create: the two-minute rule.
01:30 When an idea feels too big, find the version you can start in two minutes.
01:39 Open the document. Record one sentence. Sketch one shape.
01:48 Small starts remove friction. And momentum does the rest.
01:58 Your audience doesn't need perfect. They need something honest.
02:07 Think about the last video you shared with a friend. What made you send it?
02:17 It probably made you feel understood, surprised, or a little less alone.
02:27 That's the goal. Make one person feel something, and give them a reason to pass it on.
02:38 So take the idea you've been sitting on, and make the smallest version today.
02:48 Start before you're ready. Your future self will thank you.`;
let state={demo:true,videoId:null,clips:[],selected:0,cues:[],style:'lime'};
const escapeHTML=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function seconds(t){return t.replace(',','.').split(':').reduce((n,v)=>n*60+Number(v),0)}
function stamp(n){return `${Math.floor(n/60).toString().padStart(2,'0')}:${Math.floor(n%60).toString().padStart(2,'0')}`}
function parseTranscript(raw){const lines=raw.replace(/\r/g,'').split('\n'), cues=[];let current=null;for(const line of lines){const s=line.trim();if(!s||/^WEBVTT$|^\d+$/.test(s))continue;const range=s.match(/^(\d{1,2}:\d{2}:\d{2}[.,]\d{3})\s*-->\s*(\d{1,2}:\d{2}:\d{2}[.,]\d{3})/);if(range){current={start:seconds(range[1]),end:seconds(range[2]),text:''};cues.push(current);continue}const timed=s.match(/^\[?(\d{1,2}:\d{2}(?::\d{2})?(?:[.,]\d+)?)\]?\s+(.+)$/);if(timed){current={start:seconds(timed[1]),text:timed[2]};cues.push(current)}else if(current){current.text+=(current.text?' ':'')+s}else throw Error('Add a timestamp to the first line, for example: 00:00 Your opening words.')}const valid=cues.filter(c=>c.text.trim());if(!valid.length)throw Error('No timestamped speech was found.');if(valid.some((c,i)=>!Number.isFinite(c.start)||c.start<0||(i&&c.start<=valid[i-1].start)))throw Error('Use timestamps in increasing order, without duplicates.');return valid.map((c,i)=>({...c,end:c.end??valid[i+1]?.start??c.start+Math.max(3,c.text.split(/\s+/).length/2.5)})).map(c=>{if(c.end<=c.start)throw Error('Each caption must end after it starts.');return c})}
function grade(text){const opening=text.split(/(?<=[.!?])\s+/)[0];const hook=/\?|secret|nobody|here's|stop |most people|what if|but |don't/i.test(opening);const value=/tip|trick|rule|how |start|make |step|learn|try |because/i.test(text);const emotion=/feel|friend|terrible|alone|honest|confidence|permission|thank|love|fear/i.test(text);const words=text.split(/\s+/).length;const score=Math.min(94,40+(hook?20:0)+(value?16:0)+(emotion?12:0)+(words>=35&&words<=140?6:0));return {score,reason:hook&&value?'A curiosity-led opening with a practical takeaway.':emotion?'An emotional idea your audience could recognize.':'A self-contained idea worth testing with your audience.',type:hook?'Strong hook':value?'Practical takeaway':'Story moment'}}
function findHighlights(){try{const cues=parseTranscript($('transcript').value),target=Number($('clipLength').value),candidates=[];for(let i=0;i<cues.length;i++){let j=i;while(j+1<cues.length&&cues[j+1].end-cues[i].start<=target)j++;const group=cues.slice(i,j+1),duration=group.at(-1).end-cues[i].start;if(duration<Math.min(15,target/2))continue;const text=group.map(c=>c.text).join(' ');candidates.push({start:cues[i].start,end:Math.min(cues[i].start+target,group.at(-1).end),text,title:cues[i].text.split(/\s+/).slice(0,10).join(' '),...grade(text)})}candidates.sort((a,b)=>b.score-a.score);const picked=[];for(const c of candidates){if(picked.every(p=>Math.max(0,Math.min(c.end,p.end)-Math.max(c.start,p.start))<Math.min(c.end-c.start,p.end-p.start)*.3))picked.push(c);}if(!picked.length)throw Error('Add a longer transcript: at least 15 seconds of timestamped speech.');state.cues=cues;state.clips=picked;state.selected=0;$('analysisError').textContent='';render();toast(`${picked.length} highlight ideas ready`);return {count:picked.length,method:'Text-based editorial heuristic'}}catch(e){$('analysisError').textContent=e.message;throw e}}
function selected(){return state.clips[state.selected]}
function render(){const clips=state.clips.map((c,i)=>({...c,index:i})).sort($('sort').value==='time'?(a,b)=>a.start-b.start:(a,b)=>b.score-a.score);$('clipCount').textContent=`${clips.length} CLIP${clips.length===1?'':'S'}`;$('moments').innerHTML=clips.length?clips.map((c,i)=>`<button class="moment ${c.index===state.selected?'selected':''}" data-index="${c.index}" aria-pressed="${c.index===state.selected}"><div class="moment-top"><span class="moment-number">MOMENT ${String(i+1).padStart(2,'0')}</span><span class="score">${c.score}<small>/ 100 EDITORIAL</small></span></div><h4>${escapeHTML(c.title)}</h4><p>${escapeHTML(c.reason)}</p><div class="moment-meta"><span>${stamp(c.start)} – ${stamp(c.end)}</span><span>${Math.round(c.end-c.start)}s</span><b>${escapeHTML(c.type)}</b></div></button>`).join(''):'<div class="empty-moments">Your next great clip starts here.<br>Add a timestamped transcript, then select <strong>Find highlights</strong>.</div>';$('moments').querySelectorAll('button').forEach(b=>b.onclick=()=>{state.selected=Number(b.dataset.index);render()});const c=selected();$('clipTitle').value=c?.title??'';$('startTime').value=c?.start??'';$('endTime').value=c?.end??'';$('captionPreview').textContent=c?c.text.split(/\s+/).slice(0,13).join(' '):'Your next big moment.';$('previewPlatform').textContent=$('platform').value;$('exportBtn').disabled=$('srtBtn').disabled=!c;$('clipTitle').disabled=$('startTime').disabled=$('endTime').disabled=!c;$('sessionTag').textContent=state.demo?'Demo project':'YouTube project';$('sourceBadge').textContent=state.demo?'SAMPLE':'YOUTUBE';$('editError').textContent='';}
function youtubeId(url){let u;try{u=new URL(url)}catch{throw Error('Enter a full YouTube URL, including https://.')}if(!['https:','http:'].includes(u.protocol))throw Error('Use a YouTube web link.');const host=u.hostname.toLowerCase().replace(/^www\./,'');let id;if(host==='youtu.be')id=u.pathname.split('/')[1];else if(['youtube.com','m.youtube.com','music.youtube.com'].includes(host))id=u.searchParams.get('v')||u.pathname.match(/^\/(shorts|embed|live)\/([^/]+)/)?.[2];if(!id||!/^[-\w]{11}$/.test(id))throw Error('Use a valid YouTube video, Shorts, or youtu.be link.');return id}
function addVideo(url){const id=youtubeId(url);state={...state,demo:false,videoId:id,clips:[],cues:[],selected:0};$('videoUrl').value=url;$('sourceScreen').innerHTML=`<iframe src="https://www.youtube-nocookie.com/embed/${id}" title="YouTube source video" allow="accelerometer; autoplay; encrypted-media; gyroscope; picture-in-picture" allowfullscreen></iframe>`;$('sourceTitle').textContent='Your YouTube source';$('sourceMeta').textContent='Player ready · paste a transcript below to find highlights';$('transcript').value='';$('transcript').placeholder='00:00 Paste your transcript here…\n00:10 Include a timestamp for each line.';$('importError').textContent='';$('analysisError').textContent='';render();toast('Video added. Reading it automatically…');return {videoId:id,status:'awaiting_transcript'}}
function updateEdit(){const c=selected();if(!c)return false;const start=Number($('startTime').value),end=Number($('endTime').value);if(!$('startTime').value||!$('endTime').value||!Number.isFinite(start)||!Number.isFinite(end)||start<0||end<=start){$('editError').textContent='Set an end time after the start time.';return false}const maxEnd=state.cues.at(-1)?.end;if(end>maxEnd){$('editError').textContent=`The transcript ends at ${stamp(maxEnd)}. Choose an earlier end.`;return false}const text=state.cues.filter(x=>x.start<end&&x.end>start).map(x=>x.text).join(' ');if(!text){$('editError').textContent='Choose a range with transcript text.';return false}Object.assign(c,{start,end,title:$('clipTitle').value.trim()||'Untitled clip',text,...grade(text)});$('editError').textContent='';return true}
function download(content,name,type){const url=URL.createObjectURL(new Blob([content],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast(`Downloaded ${name}`)}
function srtTime(s){const ms=Math.round(s*1000);return `${String(Math.floor(ms/3600000)).padStart(2,'0')}:${String(Math.floor(ms/60000)%60).padStart(2,'0')}:${String(Math.floor(ms/1000)%60).padStart(2,'0')},${String(ms%1000).padStart(3,'0')}`}
function exportSrt(){if(!updateEdit())return;const c=selected(),cues=state.cues.filter(x=>x.start<c.end&&x.end>c.start);const srt=cues.map((x,i)=>`${i+1}\n${srtTime(Math.max(0,x.start-c.start))} --> ${srtTime(Math.min(c.end,x.end)-c.start)}\n${x.text}\n`).join('\n');download(srt,'cutroom-captions.srt','application/x-subrip')}
function exportPlan(){if(!updateEdit())return;const c=selected();download(JSON.stringify({title:c.title,source:state.videoId?`https://www.youtube.com/watch?v=${state.videoId}`:'Illustrative demo transcript',startSeconds:c.start,endSeconds:c.end,platform:$('platform').value,aspectRatio:'9:16',resolution:'1080x1920',captionStyle:state.style,transcript:c.text,potentialScore:c.score,scoreMethod:'Text-only editorial heuristic; not a prediction of views',renderStatus:'Not rendered. Connect a video processing service to export MP4.'},null,2),'cutroom-clip-plan.json','application/json')}
let toastTimer;function toast(text){$('toast').textContent=text;$('toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').classList.remove('show'),3500)}
function info(kind){$('dialogContent').innerHTML=kind==='help'?`<h2>From long-form to a little more memorable.</h2><ol><li><strong>Add your YouTube link.</strong> Watch the original in the embedded player. Some videos block embedding.</li><li><strong>Bring the words.</strong> Paste a timestamped transcript or import an SRT, VTT, or TXT file.</li><li><strong>Find your highlights.</strong> Text rules surface hooks, useful takeaways, and emotional moments. Review every suggestion against the original.</li><li><strong>Shape your short.</strong> Adjust timing and caption color, then download captions and a clip plan.</li></ol><p>This studio previews caption layout. A processing connection is needed to download a cropped, captioned MP4.</p>`:`<h2>Connect the finishing touches.</h2><p>Your studio works with links and transcripts now. These services are still needed for a fully automatic video workflow.</p><div class="connection-item"><span class="status-tag">NOT CONNECTED</span><strong>01 · Video import & transcription</strong><p>A server-side service must retrieve authorized source videos and produce timestamped speech. For now, paste or upload your transcript.</p></div><div class="connection-item"><span class="status-tag">NOT CONNECTED</span><strong>02 · Video rendering</strong><p>A hosted video processor needs to trim, crop to 9:16, track the speaker, burn in captions, and return an MP4 download. Caption styles here are layout previews only.</p></div><div class="connection-item"><span class="status-tag">OPTIONAL UPGRADE</span><strong>03 · Deeper highlight analysis</strong><p>Connect an AI analysis service for semantic scene selection and hook rewrites. Current scores use transparent text rules and are not validated viral predictions.</p></div><p>No service is connected and no API keys are stored in this page. When you choose providers, connect them through a secure backend.</p>`;$('infoDialog').showModal()}
function demo(){state={demo:true,videoId:null,clips:[],selected:0,cues:[],style:state.style};$('sourceScreen').innerHTML=sampleScreen;$('sourceTitle').textContent='The art of starting before you’re ready';$('sourceMeta').textContent='Illustrative transcript · no sample video attached';$('videoUrl').value='';$('transcript').value=sample;$('importError').textContent='';findHighlights()}
const sampleScreen=$('sourceScreen').innerHTML;
$('importForm').onsubmit=e=>{e.preventDefault();try{addVideo($('videoUrl').value.trim())}catch(e){$('importError').textContent=e.message}};
$('analyzeBtn').onclick=()=>{try{findHighlights()}catch{}};$('demoBtn').onclick=demo;$('sort').onchange=render;$('platform').onchange=()=>{$('previewPlatform').textContent=$('platform').value};$('exportBtn').onclick=exportPlan;$('srtBtn').onclick=exportSrt;
['clipTitle','startTime','endTime'].forEach(id=>$(id).onchange=()=>{if(updateEdit())render()});
document.querySelectorAll('.swatch').forEach(b=>b.onclick=()=>{state.style=b.dataset.style;$('captionPreview').style.color={lime:'#d5fa69',white:'#ffffff',pink:'#ff9ec5'}[state.style];document.querySelectorAll('.swatch').forEach(x=>{x.classList.toggle('selected',x===b);x.setAttribute('aria-pressed',String(x===b))})});
['connectionNav','setupBtn','renderBtn'].forEach(id=>$(id).onclick=()=>info('connections'));$('help').onclick=()=>info('help');$('closeDialog').onclick=()=>$('infoDialog').close();$('infoDialog').onclick=e=>{if(e.target===$('infoDialog'))$('infoDialog').close()};$('studioNav').onclick=()=>window.scrollTo({top:0,behavior:'smooth'});
$('uploadTranscript').onclick=()=>$('transcriptFile').click();$('transcriptFile').onchange=async()=>{const file=$('transcriptFile').files[0];if(!file)return;if(file.size>2000000){$('analysisError').textContent='Choose a transcript smaller than 2 MB.';return}try{$('transcript').value=await file.text();$('analysisError').textContent='';toast('Transcript imported. Select Find highlights.')}catch{$('analysisError').textContent='Could not read that file. Try a plain text transcript.'}$('transcriptFile').value=''};
demo();$('toast').classList.remove('show');
if(document.modelContext?.registerTool){const controller=new AbortController();for(const tool of [{name:'analyze_youtube_video',title:'Analyze YouTube video',description:'Automatically read captions or transcribe a YouTube video and suggest clip timestamps. Clears the current project; may download audio and a speech model.',inputSchema:{type:'object',properties:{url:{type:'string'}},required:['url'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute:async input=>{if(typeof input?.url!=='string')throw Error('A URL string is required');return addVideo(input.url)}},{name:'suggest_transcript_highlights',title:'Find transcript highlights',description:'Find text-based highlight suggestions from the transcript currently visible in the studio. Does not analyze video or predict views.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:true},execute:async input=>{if(!input||Object.keys(input).length)throw Error('No arguments expected');return findHighlights()}}]){try{Promise.resolve(document.modelContext.registerTool(tool,{signal:controller.signal})).catch(()=>{})}catch{}}window.addEventListener('pagehide',()=>controller.abort(),{once:true})}

